public class CircleTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static double round3(double x) {
        return Math.round(x * 1000.0) / 1000.0;
    }

    public static void main(String[] args) {
        Circle unit = new Circle(1.0);
        check("area of radius 1", 3.142, round3(unit.area()));
        check("perimeter of radius 1", 6.283, round3(unit.perimeter()));

        Circle two = new Circle(2.0);
        check("area of radius 2", 12.566, round3(two.area()));
        check("perimeter of radius 2", 12.566, round3(two.perimeter()));

        Measurable m = new Circle(3.0);
        check("area through a Measurable reference", 28.274, round3(m.area()));
        check("perimeter through a Measurable reference", 18.85, round3(m.perimeter()));

        Circle zero = new Circle(0.0);
        check("area of radius 0", 0.0, round3(zero.area()));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

